/* HTML: <div id="loader-d-8"></div> */
#loader-d-8 {
  width: 15px;
  aspect-ratio: 1;
  position: relative;
}
#loader-d-8::before,
#loader-d-8::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: #000;
}
#loader-d-8::before {
  box-shadow: -25px 0;
  animation: l8-1 1s infinite linear;
}
#loader-d-8::after {
  transform: rotate(0deg) translateX(25px);
  animation: l8-2 1s infinite linear;
}

@keyframes l8-1 {
    100%{transform: translateX(25px)}
}
@keyframes l8-2 {
    100%{transform: rotate(-180deg) translateX(25px)}
}
